    static final String SHA=String.join("",Collections.nCopies(64,"a"));

    // Source selection identity.
        @Test void explicitSelectionRejectsUnreadyForeignAndNonTemplateIdsWhileOmittedFreezesEligibleTemplates(){
            List<Object[]> rows=new ArrayList<>(Arrays.asList(metadata(1,"STANDARD_TEMPLATE","NTT","PARSED"),metadata(2,"STANDARD_TEMPLATE","SCT","PARTIAL"),metadata(3,"STANDARD_TEMPLATE","SCC","PARSED"),metadata(4,"PROJECT_INPUT",null,"PARSED"),metadata(5,"STANDARD_TEMPLATE","SCC","PARSING"),metadata(6,"STANDARD_TEMPLATE",null,"IDENTITY_PENDING")));
            assertEquals(set("1","2","3"),DraftAutomationService.selectSources(rows,null));assertEquals(set("2","3"),DraftAutomationService.selectSources(rows,Arrays.asList("3","2")));
            for(List<String> invalid:Arrays.asList(Collections.<String>emptyList(),Arrays.asList("2","2"),Collections.singletonList("STD-SCT"),Collections.singletonList("4"),Collections.singletonList("5"),Collections.singletonList("6"),Collections.singletonList("999")))assertThrows(BizException.class,()->DraftAutomationService.selectSources(rows,invalid),invalid.toString());
            Set<String> frozen=DraftAutomationService.selectSources(rows,null);rows.add(metadata(7,"STANDARD_TEMPLATE","SCT","PARSED"));assertFalse(frozen.contains("7"));
        }
