        @Test void selectedInputRetainsTheSavedHumanGraphAndItsExplicitSccWhileFreezingArchiveDependencies(){
            SourceDocumentRepository sources=mock(SourceDocumentRepository.class);DraftReviewSources reader=mock(DraftReviewSources.class);DraftTemplateGraphHeadRepository heads=mock(DraftTemplateGraphHeadRepository.class);DraftTemplateGraphRevisionRepository revisions=mock(DraftTemplateGraphRevisionRepository.class);DraftTemplateGraphHead head=new DraftTemplateGraphHead();head.setProjectId("p");head.setDraftRevisionId("base");when(heads.findById("p")).thenReturn(Optional.of(head));SourceDocument ntt=document(1,"NTT"),sct=document(2,"SCT"),pdf=document(3,"SCC"),word=document(4,"SCC");when(sources.findDraftReviewSourcesByProjectIdAndCategory("p","STANDARD_TEMPLATE")).thenReturn(Arrays.asList(ntt,sct,pdf,word));when(sources.findDraftReviewSourceByProjectIdAndId("p",1L)).thenReturn(Optional.of(ntt));when(sources.findDraftReviewSourceByProjectIdAndId("p",3L)).thenReturn(Optional.of(pdf));when(reader.readingCompact(sct)).thenReturn(source("2","SCT"));when(reader.readingCompact(word)).thenReturn(source("4","SCC"));ObjectNode nttArchive=JsonUtils.mapper().valueToTree(identity("1","NTT","docx")),pdfArchive=JsonUtils.mapper().valueToTree(identity("3","SCC","pdf"));when(reader.archive(ntt)).thenReturn(nttArchive);when(reader.archive(pdf)).thenReturn(pdfArchive);
            Map<String,Object> saved=graph();map(saved.get("selectedDocuments")).put("SCC","3");DraftBusinessRules.list(saved.get("sources")).add(identity("3","SCC","pdf"));state(saved).put("sourceTaskCoverage",Collections.singletonList(obj("sourceId","1","status","human-reviewed")));state(saved).put("requirements",Collections.singletonList(obj("id","retained-human-duty","sourceId","1")));String before=JsonUtils.write(saved);DraftTemplateGraphRevision revision=new DraftTemplateGraphRevision("base","p",null,"DRAFT","hash",before,JsonUtils.write(Arrays.asList(nttArchive,pdfArchive)),Instant.now());when(revisions.findByIdAndProjectId("base","p")).thenReturn(Optional.of(revision));DraftTemplateGraphService service=new DraftTemplateGraphService(mock(ProjectService.class),sources,revisions,heads,null,null,null,reader,null,null,null,null);assertEquals(set("1","3"),service.automationSourceDependencies("p","base"));List<JsonNode> readings=new ArrayList<>();Map<String,Object> result=service.automationInput("p",null,"base",set("2","4"),readings);assertEquals(state(saved),state(result));assertEquals("3",map(result.get("selectedDocuments")).get("SCC"));assertEquals(before,revision.getGraphJson());verify(reader,never()).readingCompact(ntt);verify(reader,never()).readingCompact(pdf);assertEquals(2,readings.size());
        }
    // Retained human graph and per-source audit.
        @Test void identicalMemberAndMarkerPathsCannotRetireOrRewriteUnselectedNtt(){
            for(String status:Arrays.asList("excluded","confirmed","changed")){
                Map<String,Object> graph=graph();DraftAutomaticDiscovery.Plan plan=DraftAutomaticDiscovery.plan(Collections.singletonList(source("2","SCT")),graph);Map<String,Object> task=plan.tasks().get(0);
                Map<String,Object> human=obj("id","human-ntt","nameZh","人工变量","nameEn","Human NTT","type",obj("kind","text"),"role",obj("kind","input"),"status",status,"manual",true,"docIds",Collections.singletonList("1"),"sourceAnchors",Collections.singletonList(obj("docId","1","text","Provide project fact.")),"editTargets",new ArrayList<>(),"options",new ArrayList<>());
                Map<String,Object> seed=obj("id","ntt-source","nameZh","来源","nameEn","NTT source","definitionKind","source_seed","type",obj("kind","text"),"role",obj("kind","verification"),"status","pending","manual",false,"docIds",Collections.singletonList("1"),"sourceAnchors",new ArrayList<>(),"editTargets",new ArrayList<>(),"options",new ArrayList<>(),"discoverySourceKey",task.get("sourceKey"));
                state(graph).put("variables",new ArrayList<>(Arrays.asList(human,seed)));Map<String,Object> oldCoverage=obj("sourceId","1","sourceSha256",SHA,"scanStatus","partial","memberCoverage",Collections.singletonList(obj("memberId","shared-member","status","unknown")));Map<String,Object> oldGroup=obj("id","ntt-group","sourceIds",Collections.singletonList("1"),"taskIds",Collections.singletonList("ntt-task"),"status","partial");state(graph).put("automaticDiscovery",obj("sources",Collections.singletonList(oldCoverage),"groups",Collections.singletonList(oldGroup)));
                Object sourceTaskCoverage=Collections.singletonList(obj("sourceId","1","fileKey","NTT","markerId","shared-note","nodeIds",Collections.singletonList("human-ntt")));state(graph).put("sourceTaskCoverage",sourceTaskCoverage);state(graph).put("requirements",new ArrayList<>());state(graph).put("relationProposals",new ArrayList<>());String before=JsonUtils.write(graph),humanBefore=JsonUtils.write(human),seedBefore=JsonUtils.write(seed);
                Map<String,Object> receipt=DraftAutomaticDiscovery.process((system,user)->"{\"requirements\":[],\"nodes\":[]}",plan,task),result=DraftAutomaticDiscovery.finish(graph,plan,Collections.singletonList(receipt));
                assertEquals(humanBefore,JsonUtils.write(nodes(result).stream().filter(node->"human-ntt".equals(node.get("id"))).findFirst().orElseThrow()));assertEquals(seedBefore,JsonUtils.write(nodes(result).stream().filter(node->"ntt-source".equals(node.get("id"))).findFirst().orElseThrow()));assertEquals(JsonUtils.write(sourceTaskCoverage),JsonUtils.write(state(result).get("sourceTaskCoverage")));assertTrue(list(state(result).get("requirements")).isEmpty());assertTrue(list(state(result).get("relationProposals")).isEmpty());
                Map<String,Object> audit=map(state(result).get("automaticDiscovery"));assertEquals("completed",audit.get("scanStatus"));assertEquals("partial",audit.get("allSourcesScanStatus"));assertTrue(list(audit.get("sources")).contains(oldCoverage));assertTrue(list(audit.get("groups")).contains(oldGroup));assertEquals(Collections.singletonList("2"),audit.get("selectedSourceIds"));assertEquals(before,JsonUtils.write(graph));
            }
        }
